-- 014 · Definiciones de los roles según la narrativa del home (bloque 7, borrador del 29-sep-2026).
update public.cat_role set description = 'Facilitan la conexión, coordinación y alineación entre los distintos actores. Aseguran que los esfuerzos individuales se integren en una estrategia común y que se mantenga el rumbo colectivo.' where code = 'articulador';
update public.cat_role set description = 'Ejecutan las acciones en campo. Transforman los planes en programas, proyectos o servicios concretos que impactan directamente a los jóvenes u otras poblaciones objetivo.' where code = 'implementador';
update public.cat_role set description = 'Aportan los recursos económicos, técnicos o en especie necesarios para la operación de las iniciativas. A veces también acompañan la definición estratégica para garantizar el retorno social de la inversión.' where code = 'financiador';
update public.cat_role set description = 'Definen el rumbo estructural del ecosistema a través de políticas públicas, lineamientos institucionales o decisiones gremiales. Tienen la capacidad de habilitar condiciones, escalar soluciones e incidir en transformaciones de alto impacto.' where code = 'tomador_decision';
update public.cat_role set description = 'Miden el impacto, sistematizan aprendizajes y aportan evidencia para la toma de decisiones y la mejora continua del Colaborativo.' where code = 'evaluador';
update public.cat_role set description = 'Son el centro del Colaborativo, pero no solo como receptores, sino como actores activos que co-diseñan, validan y transforman las soluciones desde su experiencia y voz.' where code = 'juventud';
update public.cat_role set description = 'Movilizan voluntades, abren puertas y posicionan los temas clave en la agenda pública o privada. Usan su reputación o capacidad de incidencia para generar cambios sistémicos.' where code = 'embajador';
